                    T event = parser.parse(line);
                    long ts = timestampExtractor.extractTimestamp(event);
                    synchronized (lock) {
                        ctx.collectWithTimestamp(event, ts);
                        if (ts > lastWatermark) {
                            ctx.emitWatermark(new Watermark(ts));
                            lastWatermark = ts;
                        }
                    }
                }

                synchronized (lock) {
                    ctx.emitWatermark(new Watermark(Long.MAX_VALUE));
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

